import{_ as a,a0 as r,w as u,s as p,ao as l,I as i,x as n,a1 as s,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"[小白技巧]如何在Linux中知道你的系统是否有USB 3.0 端口 | LCTT x X-CMD","titleTemplate":false,"description":"[小白技巧]如何在Linux中知道你的系统是否有USB 3.0 端口 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"[小白技巧]如何在Linux中知道你的系统是否有USB 3.0 端口 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"[小白技巧]如何在Linux中知道你的系统是否有USB 3.0 端口 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140609 How To Know If Your System Has USB 3.0 Port In Linux [Quick Tip]","title":"[小白技巧]如何在Linux中知道你的系统是否有USB 3.0 端口","tag":"201406","desc":""},"relativePath":"201406/20140609 How To Know If Your System Has USB 3.0 Port In Linux [Quick Tip].md","filePath":"[post].md"}'),d={name:"201406/20140609 How To Know If Your System Has USB 3.0 Port In Linux [Quick Tip].md"};function S(x,t,f,m,B,U){const o=r("Link");return u(),p("div",null,[t[11]||(t[11]=l(`<h1 id="小白技巧-如何在linux中知道你的系统是否有usb-3-0-端口" tabindex="-1">[小白技巧]如何在Linux中知道你的系统是否有USB 3.0 端口 <a class="header-anchor" href="#小白技巧-如何在linux中知道你的系统是否有usb-3-0-端口" aria-label="Permalink to “[小白技巧]如何在Linux中知道你的系统是否有USB 3.0 端口”">​</a></h1><p>近来的大多数的新计算机都有了USB 3.0接口了。但是<strong>你怎么知道你的计算机有没有USB 3.0接口</strong>？这篇短文中，我们会告诉如何在Linux下知道你的系统上有USB 3还是USB3接口。</p><h3 id="在linux终端中检测是否有usb-3-0-端口" tabindex="-1">在Linux终端中检测是否有USB 3.0 端口 <a class="header-anchor" href="#在linux终端中检测是否有usb-3-0-端口" aria-label="Permalink to “在Linux终端中检测是否有USB 3.0 端口”">​</a></h3><p>打开一个终端,并使用下面的命令:</p><pre><code>lsusb
</code></pre><p>这个命令会显示你系统下USB的总线信息。检查一下结果，如果你看到像“3.0 root hub”字样，这意味着你系统有USB 3.0。比如，在我的电脑上，它这样显示：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/06/Know_Usb3_Ubuntu_Linux.jpeg" alt="How to find if system has USB 3.0 in Linux"></p><p>这个技巧在所有的Linux系统上，像Ubuntu，Linux Mint，Fedora等等都有效。现在当你知道你有USB 3.0 端口之后，**如何辨别哪个口是USB 3.0,哪个是USB 2.0。</p><h3 id="辨别哪个口是usb-3-0" tabindex="-1">辨别哪个口是USB 3.0 <a class="header-anchor" href="#辨别哪个口是usb-3-0" aria-label="Permalink to “辨别哪个口是USB 3.0”">​</a></h3><p>通常USB 3.0 口被标记为SS（“Super Speed”的缩写）。如果你的系统制造商没有标记SS或者USB 3,那么你可以检查端口的内部通常是蓝色的。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/06/usb3.0port.jpg" alt="find usb 3.0 port"></p><p>我希望这个快捷提示能够帮助你知道你系统是否有USB 3.0 并可以分辨出USB 3.0 口</p><hr>`,13)),i("p",null,[t[1]||(t[1]=n("via: ",-1)),s(o,{href:"http://itsfoss.com/find-usb-3-port-linux/"},{default:e(()=>[...t[0]||(t[0]=[n("http://itsfoss.com/find-usb-3-port-linux/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=n("译者：",-1)),s(o,{href:"https://github.com/geekpi"},{default:e(()=>[...t[2]||(t[2]=[n("geekpi",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),s(o,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const b=a(d,[["render",S]]);export{_ as __pageData,b as default};
